// Protocol data generated by tools/fetch_vanilla_data.py (packet IDs, registries, flat chunk).
#pragma once
#include <cstdint>
#include <map>
#include <string>
#include <vector>

namespace pn {

struct PacketIds {
    // handshake/status/login are fixed by the protocol but still read from the table for consistency
    int st_status_response, st_pong_response, st_status_request, st_ping_request;
    int lg_disconnect, lg_finished, lg_compression, lg_hello, lg_acknowledged, lg_encrypt_req, lg_encrypt_resp;
    int cf_custom_payload, cf_disconnect, cf_finish, cf_keep_alive, cf_known_packs, cf_registry_data;
    int cfs_client_information, cfs_finish, cfs_keep_alive, cfs_known_packs, cfs_pong;
    int pl_login, pl_abilities, pl_commands, pl_position, pl_spawn, pl_game_event, pl_center, pl_time,
        pl_batch_start, pl_batch_finish, pl_chunk, pl_forget, pl_keep_alive, pl_disconnect, pl_system_chat,
        pl_player_info;
    int pls_teleport_confirm, pls_chat, pls_chat_command, pls_client_information, pls_keep_alive,
        pls_move_pos, pls_move_pos_rot, pls_move_rot, pls_move_status, pls_batch_received, pls_pong;
};

struct VanillaData {
    std::string version;
    int protocol = 0;
    int dim_type_overworld = 0;
    int biome_plains = 0;
    std::vector<std::vector<uint8_t>> config_packets;  // full packets (id + payload), vanilla order
    std::vector<uint8_t> chunk_template;               // chunk packet payload after the X/Z ints
    std::vector<uint8_t> set_time;                     // play set_time payload
    PacketIds id{};
    size_t index_known_packs = 0;  // position of the known-packs packet inside config_packets
    std::string blocks_path;       // vanilla-<ver>.blocks (block state report)
    std::map<std::string, int> reg;  // "entity_type/player", "biome/plains", "block_entity_type/chest", "item/stone"
    std::map<std::string, int> pid;  // every packet id by "play/c/add_entity"
    std::vector<std::string> biomes; // biome names in registry order
    std::vector<std::string> items;  // item names (minecraft:stone) by registry id
    int data_version = 0;
    int reg_id(const std::string& k, int def = -1) const { auto it = reg.find(k); return it == reg.end() ? def : it->second; }
    int packet(const char* k) const { auto it = pid.find(k); return it == pid.end() ? -1 : it->second; }
};

// All vanilla-*.bin files in the first directory that has any (cfg_dir, ./data, <exe>/data, <exe>/../data).
std::vector<std::string> list_vanilla_bins(const std::string& cfg_dir, const std::string& exe_dir);
// Path of data/<name> in the first data directory that has it (cfg_dir, ./data, <exe>/data, <exe>/../data), or empty.
std::string find_data_file(const std::string& cfg_dir, const std::string& exe_dir, const std::string& name);
bool load_vanilla_file(const std::string& bin, VanillaData& out, std::string& err);

}  // namespace pn
